(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">असली हाथों को अपना संगीत बजाते देखें।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">फिर इसे अपने DAW में खींचें।</span>","hero.cycle":"फिर इसे अपने DAW में खींचें।|हर नोट पढ़ें।|सीखें कि इसे कैसे बजाया जाता है।","hero.sub":"कॉर्ड्स, एक धुन, एक बेसलाइन और एक काउंटरमेलोडी, किसी भी शैली में लिखे गए, शीट म्यूज़िक के रूप में दिखाए गए और यथार्थवादी हाथों द्वारा यथार्थवादी वाद्यों पर बजाए गए, पियानो और गिटार से लेकर पूरे बैंड तक। साथ में संगीत के पाठ, जो आपको इसे ख़ुद बजाना, लिखना और अरेंज करना सिखाते हैं। ऑफ़लाइन और 100% AI-मुक्त।","hero.chipStandalone":"स्टैंडअलोन","what.title":"यह क्या है","what.p1":"कॉर्ड जनरेटर इस्तेमाल करने वाले ज़्यादातर लोग कभी नहीं देखते कि उसके हिस्से कैसे बजाए जाएँगे, और कोई वाद्य सीखने वाले ज़्यादातर लोग कभी किसी वादक के हाथ क़रीब से नहीं देखते। Handscore आपको दोनों दिखाता है।","what.p2":"कोई जॉनर, कलाकार या प्रोड्यूसर चुनें और Handscore उस शैली में चार हिस्से लिखता है: कॉर्ड्स, एक धुन, एक बेसलाइन और एक काउंटरमेलोडी। वे वाद्य के म्यूज़िक स्टैंड पर शीट म्यूज़िक के पन्नों के रूप में दिखते हैं, और यथार्थवादी हाथ उन्हें वैसे ही बजाते हैं जैसे उस वाद्य का कोई वादक बजाता: हर उंगली उसी कुंजी पर जिसे कोई पियानोवादक इस्तेमाल करता, हर फ़्रेट और स्ट्रम वैसा ही जैसा कोई गिटारवादक करता। पहले पियानो आते हैं, फिर गिटार और बास गिटार, और उनके बाद वाद्यों का हर परिवार, पूरे बैंड तक।","what.p3":"हर नोट वहीं दिखाया जाता है जहाँ वह बजाया जाता है, और पियानो की हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है, ताकि आप ठीक-ठीक देख सकें कि क्या बज रहा है। जब कोई हिस्सा सही लगे, तो उसे उसकी शीट से सीधे अपने DAW के किसी ट्रैक पर खींच लें।","what.p4":"और यह सिखाता भी है। पाठ पहले दिन पियानो पर शुरू होते हैं, आपको बजाते हुए सुनते हैं और आपके सही बजाने पर आगे बढ़ते हैं, फिर शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, थ्योरी, सॉन्गराइटिंग और गीत के बोल, गाने का अरेंजमेंट, मिक्सिंग और फ़िंगर ड्रमिंग तक जाते हैं।","inside.title":"यह क्या करेगा","inside.instruments.title":"वाद्यों का हर परिवार","inside.instruments.body":"पहले चार असली पियानो, फिर गिटार और बास गिटार; उनके बाद ऑर्गन, मैलेट वाद्य, हार्प, गज़ से बजने वाले तार वाद्य, वुडविंड, ब्रास और एक ड्रम किट, एक-एक परिवार करके, पूरे बैंड तक।","inside.hands.title":"यथार्थवादी हाथ","inside.hands.body":"दो हाथ जो हर नोट वैसे ही बजाते हैं जैसे उस वाद्य का कोई वादक बजाता: वही उंगली जो कोई पियानोवादक चुनता, वही फ़्रेट और स्ट्रोक जो कोई गिटारवादक इस्तेमाल करता।","inside.lessons.title":"संगीत के पाठ","inside.lessons.body":"पियानो पर आपके पहले नोट्स से लेकर शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, थ्योरी, सॉन्गराइटिंग और गीत के बोल, गाने का अरेंजमेंट और मिक्सिंग तक के कोर्स। ये आपको बजाते हुए सुनते हैं, और जब आप ज़ोर से पढ़ें स्विच चालू करते हैं तो हर पाठ आपको पढ़कर सुनाते हैं।","inside.drums.title":"फ़िंगर ड्रमिंग","inside.drums.body":"ड्रम पैटर्न, जनरेट किए गए या एक ऐसे पैड कंट्रोलर पर बजाकर डाले गए जिसके पैड हर हिट पर रोशन होते हैं, और पहली बीट से लेकर पूरे ग्रूव तक एक कोर्स।","inside.sheets.title":"शीट म्यूज़िक के चार पन्ने","inside.sheets.body":"कॉर्ड्स, धुन, काउंटरमेलोडी और बास, हर एक अपनी अलग शीट पर, और हर नोट बजते समय रोशन होता है।","inside.styles.title":"हर शैली जिसे Freally MIDI Master जानता है","inside.styles.body":"73 जॉनर, 1,507 कलाकार और 833 प्रोड्यूसर, उन्हीं नियम-आधारित जनरेटरों से।","inside.drag.title":"MIDI खींचें","inside.drag.body":"एक बार में एक हिस्सा या चारों एक साथ, शीट्स से सीधे आपके DAW में खींचे गए, या MIDI फ़ाइल के रूप में या शीट्स की PDF के रूप में सहेजे गए।","inside.views.title":"सामने, ऊपर और बगल के व्यू","inside.views.body":"संगीत बजते समय इनके बीच बदलें; शीट्स पढ़ने लायक बने रहने के लिए घूम जाती हैं और हाथ कभी कोई नोट नहीं चूकते।","inside.daw.title":"किसी भी DAW में","inside.daw.body":"CLAP, VST3 और AU, साथ ही एक स्टैंडअलोन ऐप। Windows, macOS और Linux।","inside.offline.title":"ऑफ़लाइन, बिना AI","inside.offline.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं, कोई मॉडल नहीं। हर हिस्सा, फ़िंगरिंग और हरकत नियमों से आती है, जिसे केवल वादा नहीं बल्कि एक बिल्ड गेट लागू करवाता है।","ladder.title":"1.0 की ओर रास्ता, और आगे 2.0 तक","ladder.intro":"हर संस्करण के लिए एक पंक्ति। पाठ, फ़िंगर ड्रमिंग, गिटार और बास गिटार 1.0 से पहले आते हैं। उसके बाद, हर संस्करण वाद्यों का एक नया परिवार लाता है, जिन्हें यथार्थवादी हाथ वैसे बजाते हैं जैसे कोई शिक्षक आपको दिखाता।","ladder.rung.v0.1.0":"नींव: प्लगइन CLAP, VST3 और AU के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, अपने लाइसेंस की स्वीकृति माँगता है, और 88 कुंजियों वाले कीबोर्ड पर खुलता है जिसकी हर कुंजी का नाम लिखा है।","ladder.rung.v0.2.0":"असली पियानो: ग्रैंड, अकूस्टिक, अपराइट और होंकी-टोंक, बजते समय उनकी कुंजियाँ हिलती और बजती हैं।","ladder.rung.v0.3.0":"कीबोर्ड पर यथार्थवादी हाथ, हर नोट की फ़िंगरिंग वैसे ही करते हुए जैसे कोई पियानोवादक करता, साथ में सीखने के लिए बासठ पब्लिक-डोमेन क्लासिक्स और सुनते हुए उनमें आगे-पीछे जाने के लिए एक ट्रांसपोर्ट।","ladder.rung.v0.4.0":"किसी भी शैली में जनरेट करें, चारों शीट्स को रोशन होते हुए पढ़ें, और MIDI को अपने DAW में खींचें।","ladder.rung.v0.5.0":"ऊपर और बगल के व्यू, शीट्स पियानो पर सपाट रखी हुई, और व्यू के बीच सहज बदलाव।","ladder.rung.lessons-1":"पहले दिन से पाठ: एक पियानो कोर्स जो आपको बजाते हुए सुनता है और आपके सही बजाने पर आगे बढ़ता है, और एक ज़ोर से पढ़ें स्विच जो हर पाठ आपको पढ़कर सुनाता है, बोले जाते समय हर शब्द रोशन करते हुए।","ladder.rung.mixer":"हर हिस्से के लिए एक मिक्सर, फ़ेडर, पैन, EQ, इफ़ेक्ट्स और कंप्रेशन के साथ, और खींचने पर भी मिक्स बना रहता है।","ladder.rung.song-view":"सॉन्ग व्यू: सेक्शन-दर-सेक्शन ख़ुद एक पूरा गाना बनाएँ, या किसी कलाकार या जॉनर के अरेंजमेंट से शुरुआत करें, फिर उसे बजते हुए देखें और अपने DAW में खींच लें।","ladder.rung.lessons-2":"और कोर्स: शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, Nashville Number System के साथ म्यूज़िक थ्योरी, सॉन्गराइटिंग और गीत के बोल, अरेंजिंग और मिक्सिंग।","ladder.rung.finger-drumming":"एक पैड कंट्रोलर पर फ़िंगर ड्रमिंग, जिसके पैड हर हिट पर रोशन होते हैं, पहली बीट से लेकर पूरे ग्रूव तक।","ladder.rung.live-listening":"लाइव लिसनिंग: किसी असली वाद्य को माइक्रोफ़ोन या इंस्ट्रूमेंट केबल के ज़रिए बजाएँ, और पाठ उसे सुनते हैं।","ladder.rung.guitars":"गिटार: अकूस्टिक, नायलॉन, इलेक्ट्रिक और म्यूटेड, असली फ़्रेटिंग, पिकिंग और स्ट्रमिंग के साथ।","ladder.rung.bass":"बास गिटार, उंगलियों से बजाया गया और स्लैप किया गया।","ladder.rung.own-audio":"आपका अपना ऑडियो और MIDI, हिस्सों में पढ़ा गया और हाथों द्वारा बजाया गया।","ladder.rung.classics":"क्लासिक्स: देखने और सुनने के लिए पब्लिक-डोमेन धुनें।","ladder.rung.realism":"यथार्थवाद का दौर: रोशनी, मटीरियल और हरकत, फ़िल्माए गए वादन की कसौटी पर।","ladder.rung.finish":"अंतिम रूप: सेटिंग्स, हर जगह अठारह भाषाएँ, सुगम्यता और मैनुअल।","ladder.rung.v1.0.0-beta.1":"अपडेट सूचनाएँ और ट्रायल तथा पेड संस्करण।","ladder.rung.v1.0.0":"पहली सार्वजनिक रिलीज़।","ladder.rung.v1.1.0":"इलेक्ट्रिक पियानो और ऑर्गन, ऑर्गन बेसलाइन के लिए पेडलबोर्ड के साथ।","ladder.rung.v1.2.0":"हार्प्सीकॉर्ड, क्लैविनेट, चेलेस्टा और खिलौना पियानो; यूकुलेले, बैंजो और मैंडोलिन।","ladder.rung.v1.3.0":"मैलेट वाद्य: ज़ाइलोफ़ोन, मरिम्बा, वाइब्राफ़ोन और ग्लॉकेनस्पील।","ladder.rung.v1.4.0":"हार्प, कोटो, सितार और माउंटेन डल्सिमर।","ladder.rung.v1.5.0":"वायलिन, वायोला, चेलो और डबल बास, गज़ से और उंगलियों से छेड़कर।","ladder.rung.v1.6.0":"फ़्लूट, क्लैरिनेट, सैक्सोफ़ोन, ओबो और रिकॉर्डर।","ladder.rung.v1.7.0":"ट्रम्पेट, ट्रॉम्बोन, फ़्रेंच हॉर्न और ट्यूबा।","ladder.rung.v1.8.0":"एक ड्रम किट, जिसे वैसे ही सेट किया और बजाया गया है जैसे कोई पेशेवर ड्रमर करता।","ladder.rung.v1.9.0":"साथ बजाने और सीखने का मोड।","ladder.rung.v2.0.0":"बैंड: हर हिस्सा अपने वाद्य पर, हर एक का अपना वादक।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: 1.0.0 से पहले कोई डाउनलोड नहीं है।","honest.title":"आज यह कहाँ है","honest.start.title":"यह अभी बिल्कुल शुरुआत में है","honest.start.body":"संस्करण 0.7.0 DAW में लोड होता है और यथार्थ हाथों से बजते चार असली पियानो पर खुलता है, जिन्हें सामने से, ऊपर से या बगल से देखा जा सकता है, और संगीत बजते हुए कैमरा उनके बीच सरकता है। कोई शैली, कलाकार या प्रोड्यूसर खोजें, बनाएँ दबाएँ, और चार हिस्से उसी शैली में लिखे जाते हैं, पियानो के म्यूज़िक-डेस्क पर शीट म्यूज़िक की तरह छपते हैं और हाथ उन्हें बजाते हैं — अपने DAW में MIDI या ऑडियो के रूप में खींचने, स्वर-दर-स्वर बदलने, या MIDI या PDF के रूप में निर्यात करने के लिए तैयार। हर हिस्सा एक मिक्सर में अपनी चैनल स्ट्रिप से होकर बजता है, उसे गढ़ने के लिए एक एनवेलप एडिटर है, और वह आपके अपने किसी इंस्ट्रूमेंट पर बज सकता है। सीखने के लिए बासठ सार्वजनिक-डोमेन क्लासिक हैं, रोकने, पीछे ले जाने और गाने में घूमने के लिए एक ट्रांसपोर्ट बार है, और 400 दिनों का एक पियानो पाठ्यक्रम आपको बजाना सिखाता है और आपको बजाते हुए सुनता है। बाकी हर वाद्य और नए पाठ्यक्रम संस्करण-दर-संस्करण आते हैं, जैसा ऊपर की सीढ़ी दिखाती है।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पन्ने पर कोई बीटा नहीं, कोई प्रीव्यू बिल्ड नहीं और कोई शुरुआती पहुँच नहीं।","honest.network.title":"Handscore खुद कभी ऑनलाइन नहीं जाता","honest.network.body":"प्लगइन और स्टैंडअलोन ऐप में कोई नेटवर्किंग कोड नहीं है, और अगर कभी जोड़ा भी जाए तो एक बिल्ड गेट फेल हो जाता है। किसी हिस्से में आप जो अपना इंस्ट्रूमेंट लोड करते हैं, वह आपका है: वह अपनी अलग प्रोसेस में चलता है और वही करता है जो वह हमेशा करता है। किसी आगामी संस्करण में एक अपडेट-चेक जोड़ा जा सकता है, जो तब तक बंद रहेगा जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाएगा।","site.tagline":"असली हाथों को अपना संगीत बजाते देखें। फिर इसे अपने DAW में खींचें।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © 2026 Mike Weaver, जो Havoc Software नाम से व्यापार करते हैं। ओपन सोर्स नहीं।","footer.yours":"आप जो MIDI बनाते हैं और अपने DAW में खींचते हैं, वह आपका है। Handscore के लेखक उस पर कोई स्वामित्व का दावा नहीं करते।","featuresPage.lead":"किसी भी शैली में लिखे चार हिस्से, शीट म्यूज़िक के रूप में दिखाए गए और यथार्थवादी हाथों द्वारा यथार्थवादी वाद्यों पर बजाए गए, हर हिस्सा सीधे आपके DAW में खिंचता हुआ, और संगीत के पाठ जो आपको इसे ख़ुद बजाना, लिखना और अरेंज करना सिखाते हैं।","featuresPage.version":"यह पेज बताता है कि Freally Handscore संस्करण 1.0 क्या करेगा। आज का संस्करण 0.7.0 है: 1.0 तक की राह होम पेज पर देखें।","featuresPage.numbers.parts":"हिस्से: कॉर्ड्स, धुन, काउंटरमेलोडी और बास","featuresPage.numbers.genres":"जॉनर","featuresPage.numbers.artists":"कलाकार","featuresPage.numbers.producers":"प्रोड्यूसर","featuresPage.numbers.keys":"कुंजियाँ, हर एक का नाम उसके सामने वाले हिस्से पर","featuresPage.numbers.plugins":"प्लगइन फ़ॉर्मैट, साथ में एक स्टैंडअलोन ऐप","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Handscore आज मुफ़्त है: कोई पेड टियर नहीं, कोई सब्सक्रिप्शन नहीं और कोई खाता नहीं। अभी डाउनलोड करने को कुछ नहीं है, क्योंकि संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और बाद के संस्करण बेचे जा सकते हैं।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.pianos.title":"चार असली पियानो","featuresPage.cards.pianos.body":"एक ग्रैंड, एक अकूस्टिक, एक अपराइट और एक होंकी-टोंक पियानो, हर एक की कुंजियाँ बजते समय हिलती हैं, और उन्हीं मापी गई पियानो आवाज़ों पर बजाया गया जिन पर Freally MIDI Master बजता है।","featuresPage.cards.strings.title":"गिटार और बास गिटार","featuresPage.cards.strings.body":"अकूस्टिक, नायलॉन, इलेक्ट्रिक और म्यूटेड गिटार, असली फ़्रेटिंग, पिकिंग और स्ट्रमिंग के साथ, और बास गिटार, उंगलियों से बजाया गया और स्लैप किया गया।","featuresPage.cards.hands.title":"यथार्थवादी हाथ","featuresPage.cards.hands.body":"दो हाथ जो हर नोट वैसे ही बजाते हैं जैसे कोई वादक बजाता: वही उंगली जो कोई पियानोवादक चुनता, वही फ़्रेट और स्ट्रोक जो कोई गिटारवादक इस्तेमाल करता।","featuresPage.cards.sheets.title":"शीट म्यूज़िक के चार पन्ने","featuresPage.cards.sheets.body":"कॉर्ड्स, धुन, काउंटरमेलोडी और बास, हर एक अपनी अलग शीट पर, और हर नोट बजते समय रोशन होता है।","featuresPage.cards.styles.title":"हर शैली जिसे Freally MIDI Master जानता है","featuresPage.cards.styles.body":"73 जॉनर, 1,507 कलाकारों या 833 प्रोड्यूसरों में से एक चुनें, और वही नियम-आधारित जनरेटर उस शैली में चारों हिस्से लिखते हैं।","featuresPage.cards.yours.title":"आपका अपना ऑडियो और MIDI","featuresPage.cards.yours.body":"अपना ऑडियो या MIDI लाएँ, और Handscore उसे हिस्सों में पढ़ता है ताकि हाथ उन्हें बजा सकें।","featuresPage.cards.classics.title":"क्लासिक्स","featuresPage.cards.classics.body":"सीखने के लिए पब्लिक-डोमेन गीत, बच्चों के गीतों और कैरल से लेकर गानों और क्लासिकल थीम तक, हर एक दो हाथों के लिए अरेंज किया गया और मंच पर हाथों द्वारा बजाया गया। इनके सिर्फ़ कॉर्ड्स ही कभी Handscore से बाहर जा सकते हैं।","featuresPage.cards.lessons.title":"संगीत के पाठ","featuresPage.cards.lessons.body":"पहले दिन से एक पियानो कोर्स जो आपको बजाते हुए सुनता है और आपके सही बजाने पर आगे बढ़ता है, फिर शीट म्यूज़िक पढ़ने, रिदम, ईयर ट्रेनिंग, थ्योरी, सॉन्गराइटिंग और गीत के बोल, गाने के अरेंजमेंट और मिक्सिंग के कोर्स। ज़ोर से पढ़ें स्विच चालू करें, तो हर पाठ आपको पढ़कर सुनाया जाता है और बोले जाते समय हर शब्द रोशन होता है; बाद के कोर्स माइक्रोफ़ोन या केबल के ज़रिए किसी असली वाद्य को सुनते हैं।","featuresPage.cards.drums.title":"फ़िंगर ड्रमिंग","featuresPage.cards.drums.body":"यथार्थवादी हाथों द्वारा बजाया गया एक पैड कंट्रोलर, हर पैड हिट होते ही रोशन। कोई ड्रम पैटर्न जनरेट करें या अपना ख़ुद का बजाकर डालें, उसे लूप करें और उसमें जोड़ते जाएँ, और पहली बीट से लेकर पूरे ग्रूव तक सीखें।","featuresPage.cards.songs.title":"पूरे गाने और एक मिक्सर","featuresPage.cards.songs.body":"सेक्शन-दर-सेक्शन ख़ुद एक गाना बनाएँ या किसी कलाकार के अरेंजमेंट से शुरुआत करें, फिर हर हिस्से को उसकी अपनी चैनल स्ट्रिप पर मिक्स करें, और मिक्स बनाए रखते हुए उसे बाहर खींच लें।","featuresPage.cards.drag.title":"MIDI खींचें","featuresPage.cards.drag.body":"एक बार में एक हिस्सा या चारों एक साथ, शीट्स से सीधे आपके DAW में खींचे गए, या MIDI फ़ाइल के रूप में या शीट्स की PDF के रूप में सहेजे गए।","featuresPage.cards.views.title":"सामने, ऊपर और बगल के व्यू","featuresPage.cards.views.body":"संगीत बजते समय इनके बीच बदलें; शीट्स पढ़ने लायक बने रहने के लिए घूम जाती हैं और हाथ कभी कोई नोट नहीं चूकते।","featuresPage.cards.daw.title":"किसी भी DAW में","featuresPage.cards.daw.body":"Windows, macOS और Linux पर CLAP और VST3, macOS पर AU, और बिना DAW के काम करने के लिए एक स्टैंडअलोन ऐप।","featuresPage.cards.offline.title":"ऑफ़लाइन, बिना AI","featuresPage.cards.offline.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं और कोई मॉडल नहीं। हर हिस्सा, फ़िंगरिंग और हरकत नियमों से आती है।","featuresPage.compare.title":"आमने-सामने","featuresPage.compare.intro":"Freally Handscore 1.0 उन औज़ारों के बगल में, जिनसे लोग संगीत के हिस्से लिखते हैं या पियानो बजते हुए देखते हैं। दूसरे उत्पादों के सेल उनकी सार्वजनिक लिस्टिंग और समीक्षाओं से लिए गए हैं, जिन्हें अक्टूबर 2026 में जाँचा गया; जहाँ हम किसी बात की पुष्टि नहीं कर सके, वहाँ सेल यही बताता है।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.generate":"नामित शैलियों में नए कॉर्ड्स, धुनें और बेसलाइन लिखता है","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.row.plugin":"प्लगइन के रूप में आपके DAW के अंदर चलता है","featuresPage.compare.row.hands":"नोट बजाते हुए यथार्थवादी 3D हाथ दिखाता है","featuresPage.compare.note.library":"रचनाओं की अपनी लाइब्रेरी","featuresPage.compare.legend.part":"आंशिक","featuresPage.compare.note.fingers":"उंगलियों के नंबर, हाथ नहीं","featuresPage.compare.row.sheets":"नोट्स को शीट म्यूज़िक के रूप में दिखाता है","featuresPage.compare.legend.unknown":"पुष्टि नहीं हुई","featuresPage.compare.row.drag":"MIDI को आपके DAW में खींचता है","featuresPage.compare.row.offline":"ऑफ़लाइन, बिना AI के काम करता है","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"इन चारों में से सिर्फ़ Handscore 1.0 में हर पंक्ति है: नामित शैलियों में लिखे हिस्से, उन्हें बजाते यथार्थवादी हाथ, शीट म्यूज़िक, आपके DAW में खींचना और प्लगइन।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"Scaler 3 कहीं ज़्यादा व्यापक म्यूज़िक-थ्योरी वर्कस्टेशन है। Synthesia आपके अपने कीबोर्ड पर रचनाएँ सीखने के लिए बना है; Handscore के पाठ संस्करण 0.6 से आपको बजाते हुए सुनते हैं, लेकिन लाइव साथ बजाने के लिए संस्करण 1.9 का इंतज़ार है। AR Pianist ऑगमेंटेड रियलिटी में अपने पियानोवादक को आपके कमरे में ले आता है, जो Handscore नहीं करता।","featuresPage.compare.fineprint":"Scaler, AR Pianist और Synthesia अपने-अपने मालिकों के ट्रेडमार्क हैं, जो Freally Handscore से संबद्ध नहीं हैं। अगर कोई सेल ग़लत हो तो हमें बताएँ, हम उसे ठीक कर देंगे।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.rules.title":"नियम, मॉडल नहीं","featuresPage.why.rules.body":"हर हिस्सा, हर फ़िंगरिंग और हर हरकत नियमों से आती है, कहीं भी कोई मॉडल नहीं। वही शैली और वही सीड हर बार वही हिस्से देते हैं।","featuresPage.why.drag.title":"जो दिखता है, वही खिंचता है","featuresPage.why.drag.body":"शीट्स उसी MIDI से बनाई जाती हैं जिसे वे खींचती हैं, और हाथ ठीक वही नोट बजाते हैं, इसलिए आपके ट्रैक पर वही पहुँचता है जो आपने देखा।","featuresPage.why.real.title":"असली माप पर बना","featuresPage.why.real.body":"हर वाद्य अपने असली माप पर बना है: कीबोर्ड असली पियानो के आकार का है, और हर कुंजी अपने संतुलन बिंदु पर वैसे ही घूमती है जैसे असली कुंजी।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं और कोई क्लाउड नहीं। प्लगइन और स्टैंडअलोन ऐप कभी ऑनलाइन नहीं जाते, और अगर कभी नेटवर्किंग कोड जोड़ा जाए तो एक बिल्ड गेट फेल हो जाता है।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ कहा गया, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पन्ना संस्करण 1.0 के बारे में है, और Handscore एक-एक संस्करण करके बनाया जा रहा है, इसलिए इसका ज़्यादातर हिस्सा अभी बना नहीं है। 1.0 की ओर रास्ते का हर संस्करण अपनी स्थिति के साथ चिह्नित है।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.export":"जिस गीत की धुन किसी क्लासिक या किसी जानी-मानी धुन से मेल खाती है, वह Handscore से सिर्फ़ अपने कॉर्ड्स के रूप में बाहर जाता है।","featuresPage.limits.families":"यह पियानो, गिटार और बास गिटार बजाता है। वाद्यों का हर दूसरा परिवार 1.0 के बाद एक-एक संस्करण करके आता है, 2.0 में पूरे बैंड तक।","featuresPage.limits.learn":"इसके पाठ आपको बजाते हुए सुनते हैं, लेकिन हाथ अभी लाइव आपका अनुसरण नहीं करते: किसी भी वाद्य पर साथ बजाना संस्करण 1.9 में आता है।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पन्ने पर भी कोई नहीं।","docs.intro":"Handscore हर वाद्य-परिवार पर यथार्थ हाथों की ओर बढ़ रहा है, पियानो से लेकर फ़िंगर ड्रमिंग, गीत-लेखन और अरेंजमेंट तक के संगीत पाठों के साथ। यह मैनुअल भी संस्करण-दर-संस्करण उसके साथ बढ़ता है। अभी यह बताता है कि संस्करण 0.7.0 क्या करता है: पियानो और हाथ, तीन दृश्य, गाना बनाना, शीट म्यूज़िक, खींचना और निर्यात, एडिटर, क्लासिक, ट्रांसपोर्ट, पियानो के पाठ, मिक्सर, एनवेलप एडिटर और आपके अपने इंस्ट्रूमेंट।","docs.start.title":"शुरुआत करना","docs.agreement.title":"लाइसेंस अनुबंध","docs.stage.title":"मंच","docs.pianos.title":"पियानो","docs.play.title":"कुंजियाँ बजाना","docs.hands.title":"हाथ","docs.views.title":"दृश्य","docs.generate.title":"गाना बनाना","docs.sheets.title":"शीट म्यूज़िक","docs.tray.title":"शीट ट्रे","docs.drag.title":"अपने DAW में","docs.edit.title":"स्वरों को संपादित करना","docs.lyrics.title":"बोल","docs.seeds.title":"सीड और इतिहास","docs.classics.title":"क्लासिक्स","docs.transport.title":"ट्रांसपोर्ट","docs.lessons.title":"पाठ","docs.mixer.title":"मिक्सर","docs.envelopes.title":"एनवेलप एडिटर","docs.hosted.title":"आपके अपने इंस्ट्रूमेंट","docs.shortcuts.title":"कीबोर्ड शॉर्टकट","docs.project.title":"आपका प्रोजेक्ट","docs.theme.title":"लाइट और डार्क","docs.language.title":"भाषाएँ","docs.privacy.title":"आपकी निजता","docs.start.p1":"Handscore आपके DAW के अंदर CLAP, VST3 या AU इंस्ट्रूमेंट के रूप में, या अकेले एक स्टैंडअलोन ऐप के रूप में चलता है। इसे किसी इंस्ट्रूमेंट ट्रैक पर रखें।","docs.start.p2":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.agreement.p1":"Handscore जब पहली बार खुलता है, तो अपना लाइसेंस अनुबंध दिखाता है। जब तक आप सहमत नहीं चुनते, Handscore कुछ नहीं करता और कोई आवाज़ नहीं निकालता।","docs.agreement.p2":"आपका जवाब आपके कंप्यूटर पर रखा जाता है और Handscore की हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी। यदि आप अस्वीकार करते हैं, तो अनुबंध स्क्रीन पर बना रहता है, ताकि जब भी आप सहमत हों, वह तैयार रहे।","docs.stage.p1":"ऊपरी बार के नीचे मंच है: आपका चुना हुआ पियानो, उसकी 88 कुंजियाँ, A0 से C8 तक, असली पियानो के माप में, जो विंडो की पूरी चौड़ाई भरता है। हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है — सफ़ेद कुंजियों पर गहरी स्याही में, काली कुंजियों पर सफ़ेद में — और कुंजी दबी रहने तक छिपा रहता है, ताकि आप हमेशा देख सकें कि कौन-से नोट बजाए जा रहे हैं।","docs.stage.p2":"अगर आपका कंप्यूटर 3D में नहीं बना सकता, तो मंच कुछ भी न दिखाने के बजाय यह बताता है और समझाता है कि इसे कैसे चालू करें।","docs.stage.p3":"Handscore मापता है कि आपका कंप्यूटर मंच को कितनी तेज़ी से बनाता है, और उस गुणवत्ता पर टिक जाता है जिसे वह सहजता से बनाए रख सके।","docs.pianos.p1":"चार पियानो बारी-बारी से मंच पर आते हैं, एक बार में एक: Grand Piano, Acoustic Piano, Upright Piano और Honky-Tonk Piano, हर एक का अपना आकार, फ़िनिश और आवाज़।","docs.pianos.p2":"ऊपर बाईं ओर का मोड चुनें बटन (या P) आपके विकल्प श्रेणी के अनुसार खोलता है। वाद्य में, पूर्वावलोकन पियानो बदले बिना किसी पियानो पर एक छोटी धुन बजाता है, और चुनें उसे मंच पर रख देता है, पिछले पियानो से क्रॉसफ़ेड करते हुए। आपकी पसंद आपके प्रोजेक्ट के साथ सहेजी जाती है।","docs.play.p1":"किसी कुंजी को सुनने के लिए उस पर क्लिक करें, या कुंजियों पर से सरकाते हुए उन्हें एक-एक करके बजाएँ। हर कुंजी अपने संतुलन बिंदु पर घूमते हुए नीचे जाती है, जितनी ज़ोर से बजाई जाए उतनी तेज़ी से, और नीचे रहने तक उसका नाम धुंधला रहता है और ऊपर उठने पर लौट आता है।","docs.play.p2":"आपके DAW से आने वाला MIDI पियानो बजाता है और उसकी कुंजियाँ हिलाता है। सस्टेन पेडल आपके छोड़े हुए सुरों को तब तक थामे रखता है जब तक आप उससे पैर नहीं उठा लेते।","docs.hands.p1":"दो यथार्थवादी हाथ मंच पर हर नोट वैसे ही बजाते हैं जैसे कोई पियानोवादक बजाता: हर उंगली उस अंश के लिए चुनी हुई, स्केल पर अंगूठा नीचे से निकलता हुआ, चौड़े कॉर्ड्स तक पहुँच, और जब संगीत में हाथों को एक-दूसरे के पार जाना हो तो एक हाथ उठकर दूसरे के ऊपर से जाता हुआ। जब कुछ नहीं बज रहा होता, तो वे कुंजियों पर तैयार टिके रहते हैं।","docs.hands.p2":"Handscore संगीत बजने से पहले ही तय कर लेता है कि हर नोट कौन-सा हाथ बजाएगा और किस उंगली से, ताकि कुंजियों के नीचे जाते ही हाथ वहाँ पहुँच जाएँ।","docs.views.p1":"मंच को सामने से, ऊपर से या बगल से देखें। मंच के ऊपरी दाएँ कोने में दृश्य का नॉब घुमाएँ, या अगले दृश्य के लिए V और पिछले के लिए Shift+V दबाएँ। संगीत बजता रहता है और कैमरा एक दृश्य से अगले पर सरकता है, और हर कुंजी, हर हाथ और हर जलता सुर ठीक ताल में रहता है। आपका प्रोजेक्ट दृश्य याद रखता है।","docs.views.p2":"सामने वादक का दृश्य है, कीबोर्ड पूरी खिड़की भरता है। ऊपर सीधे कुंजियों और हाथों पर नीचे देखता है: ग्रैंड पियानो इसके लिए अपना ढक्कन बंद करता है, और स्वरलिपियाँ ढक्कन पर अगल-बगल सपाट पड़ी रहती हैं ताकि आप उन्हें पढ़ सकें; अपराइट पर वे ऊपरी ढक्कन पर रहती हैं। बगल कुंजियों की ऊँचाई पर ऊँचे सुरों वाले सिरे से कीबोर्ड के साथ-साथ देखता है और हाथों का आकार दिखाता है — हर उँगली कैसे मुड़ती है और हर कुंजी कितनी नीचे जाती है — और डेस्क पर स्वरलिपियाँ आपकी ओर घूमी रहती हैं। बगल के दृश्य में दृश्य के नॉब के नीचे का बाईं ओर से स्विच इसकी जगह गहरे सुरों वाले सिरे से देखता है। किसी भी दृश्य में स्वरलिपि को पास से देखने के लिए उस पर क्लिक करें, या 1 से 5 दबाएँ।","docs.generate.p1":"बाईं ओर का पैनल (खिड़की के किनारे पर उसका टैब उसे दिखाता और छिपाता है) 73 शैलियों, 1,507 कलाकारों और 833 प्रोड्यूसरों में खोजता है। एक चुनें और बनाएँ या G दबाएँ: चार हिस्से — कॉर्ड, धुन, प्रति-धुन और बेसलाइन — उसी शैली में, 4 या 8 बार लंबे लिखे जाते हैं, और हाथ उन्हें पियानो पर बजाते हैं।","docs.generate.p2":"बनाएँ के पास के चिप्स मूल स्वर, स्केल (41 विकल्प), मूड, टेम्पो (20 से 999 BPM; संख्या को ऊपर या नीचे खींचें), जटिलता और 4 या 8 बार तय करते हैं, और हर चिप बताता है कि गाना किसमें बना। DAW का अनुसरण आपके प्रोजेक्ट के टेम्पो पर लिखता है। बजाने योग्य हिस्सों को दो हाथों के लिए सजाता है; मूल उन्हें ठीक वैसा रखता है जैसा लिखा गया।","docs.sheets.p1":"हर हिस्सा पियानो के म्यूज़िक-डेस्क पर शीट म्यूज़िक के एक पन्ने की तरह छपता है, अपने शीर्षक और पृष्ठ संख्या के साथ, और बगल में सभी हिस्सों का पूरा स्कोर खड़ा रहता है। चलते प्लेहेड के नीचे हर स्वर-शीर्ष बजते ही जगमगाता है, और लंबा हिस्सा बजते-बजते अपने पन्ने पलटता है। किसी शीट पर क्लिक करें, या 1 से 5 दबाएँ, उसे पास लाने के लिए; Esc वापस ले जाता है।","docs.tray.p1":"मंच के नीचे, ट्रे हर हिस्से को सोलो, म्यूट, लॉक और एक नए टेक के साथ रखती है। लॉक किया हुआ हिस्सा दोबारा बनाने पर बना रहता है। टेक, सपना 1–3 और फिर सपना किसी हिस्से के तीन नए संस्करण आपके मौजूदा के बगल में देते हैं: एक चुनें और रख लें।","docs.drag.p1":"किसी हिस्से को उसकी शीट से, या सब खींचें से पूरे गाने को, सीधे अपने DAW में MIDI के रूप में खींचें। निर्यात किसी हिस्से या पूरे गाने का MIDI आपकी दी हुई फ़ाइल में सहेजता है — हर स्वर की वेलोसिटी, हर हिस्से का स्तर और पैन, टेम्पो और ताल-चिह्न के साथ।","docs.drag.p2":"PDF में निर्यात शीटों को एक कवर पेज के साथ लिखता है: शीर्षक, टेम्पो, मूल स्वर और स्केल, अवधि, बार, कुल स्वर, हर हिस्से और हर पन्ने के हिसाब से, और वाद्य। क्रेडिट जोड़ें — लेखक, गायक, प्रोड्यूसर, इस्तेमाल किए गए सैंपल और उनका स्रोत, रिकॉर्ड लेबल — टाइप करते समय सुझाए गए नामों के साथ।","docs.edit.p1":"मंच, धुन, कॉर्ड, प्रति-धुन और बेसलाइन ऊपर चलते हैं। किसी हिस्से का टैब उसका अपना पियानो रोल खोलता है, एक म्यूट बिंदु, सोलो और हिस्से को खाली करने वाले × के साथ। स्वरों को चुनें, खिसकाएँ, लंबा करें, मिटाएँ, कॉपी करें, चिपकाएँ और दोहराएँ; दायाँ क्लिक करके खींचने से स्वर हटते और लौटते हैं। हर हिस्से का अपना गेन और पैन है।","docs.edit.p2":"एक या दो बार की गिनती के बाद MIDI कीबोर्ड से रोल में रिकॉर्ड करें। रोल को गाने के स्केल पर, या स्वरों वाली पंक्तियों पर समेटें: स्केल की पंक्तियाँ रंगी होती हैं और उससे बाहर का स्वर चिह्नित होता है। जैसे-जैसे आप बनाते हैं, अगला स्वर या कॉर्ड हल्का-सा सुझाया जाता है; Tab उसे रखता है, एक क्लिक एक को रखता है, और कहीं और बनाने से सुझाव हट जाते हैं।","docs.edit.p3":"ट्रांसपोर्ट के पास कॉर्ड चालू करें और एक कुंजी गाने के मूल स्वर में 3, 4 या 5 स्वरों का कॉर्ड बजाती है — माउस, कंप्यूटर कीबोर्ड या MIDI कीबोर्ड से।","docs.lyrics.p1":"धुन या प्रति-धुन के नीचे शब्द लिखें, अक्षर चिह्नित करके: वे शीट पर छपते हैं और गाए जाते समय जगमगाते हैं। हर पंक्ति के पास एक गिनती बताती है कि वह अपने बार में समाती है या नहीं। टाइप करते समय शब्द का बाकी हिस्सा सुझाया जाता है (Tab उसे ले लेता है) और ग़लत वर्तनी सुधारी जाती है, जब तक आप अपना शब्द रखने के लिए चेकमार्क न छुएँ या Shift+Tab न दबाएँ।","docs.seeds.p1":"हर रचना अपना सीड दिखाती है, और हर हिस्सा अपना टेक सीड, कॉपी के साथ। किसी गाने का सीड चिपकाएँ उसे फिर से बनाने के लिए, या किसी हिस्से का टेक सीड वह टेक वापस लाने के लिए। पीछे और आगे आपकी हर रचना से गुज़रते हैं — हर एक ठीक वैसी ही लौटती है और रीस्टार्ट के बाद भी बनी रहती है; नई रचना कभी पुरानी को नहीं दोहराती।","docs.classics.p1":"मोड चुनें के क्लासिक गीत में सीखने के लिए बासठ पब्लिक-डोमेन गीत हैं: बच्चों के गीत, क्रिसमस गीत और कैरल, लोकगीत, स्पिरिचुअल और गान, क्लासिकल थीम और पियानो के लोकप्रिय गीत। हर एक दो हाथों के लिए अरेंज किया गया है, धुन दाएँ हाथ में और कॉर्ड्स बाएँ में। शीर्षक या संगीतकार से खोजें, फिर चलाएँ चुनें।","docs.classics.p2":"क्लासिक सीखने के लिए है, ले जाने के लिए नहीं: Handscore से सिर्फ़ उसके कॉर्ड बाहर जा सकते हैं। बनाया गया कोई गाना जिसकी धुन, प्रति-धुन या बेसलाइन किसी जानी-मानी धुन से मिलती हो, उस हिस्से को ऐप में ही रखता है और कारण बताता है।","docs.transport.p1":"मंच के नीचे: पीछे करना, चलाना या रोकना, बंद करना और आगे करना, और एक टाइमलाइन जिसमें गीत का समय और हर बार पर एक निशान है। उस पल के हाथ एक छोटे पूर्वावलोकन में देखने के लिए टाइमलाइन पर पॉइंटर ले जाएँ; वहाँ जाने के लिए क्लिक करें या खींचें। तेज़ी से आगे-पीछे जाने के लिए पीछे करें या आगे करें को दबाए रखें। दोनों तरह से आप हर वह नोट सुनते हैं जिससे आप गुज़रते हैं। स्पेस चलाता और रोकता है, और टाइमलाइन पर तीर कुंजियाँ एक-एक बार आगे-पीछे करती हैं।","docs.transport.p2":"कुंजियों के पास वाला M मेट्रोनोम है। इसे चालू करें, तो हर बीट पर एक क्लिक होता है, हर बार की पहली बीट ऊँची, जबकि इसके दो बिंदु बीट दिखाते हैं।","docs.transport.p3":"जब गाने में बोल हों, तो टाइमलाइन का प्रीव्यू उस पल गाए जा रहे शब्द दिखाता है।","docs.lessons.p1":"मोड चुनें → पाठ स्टूडियो के भीतर ही पियानो पाठ्यक्रम खोलता है: बाईं ओर पाठ्यक्रम का नक्शा और दिन के चरण, बीच में मंच और उसके नीचे पाठ का पाठ्य। पाठ्यक्रम दिन-ब-दिन चलता है — शुरुआती, दिन 1 से 90, फिर प्राथमिक, दिन 91 से 400 — हर दिन एक निर्देशित सत्र, और हर सप्ताह दोहराने का एक दिन। पहली बार यह दिन 1 पर खुलता है; उसके बाद जारी रखें आपको सीधे उसी दिन, चरण और शब्द पर ले जाता है जहाँ आप रुके थे। कोई भी दिन नक्शे से खोला जा सकता है, और पाठ से बाहर निकलें आपको उसी गीत पर लौटाता है जिसे आप छोड़कर आए थे।","docs.lessons.p2":"हर चरण पढ़ता है, दिखाता है या सुनता है। देखें: हाथ अभ्यास को उस दृश्य में बजाते हैं जो चरण बताता है, कहा जाए तो धीरे, उँगलियों के अंकों के साथ। आज़माएँ: बजाने वाली कुंजियाँ जगमगाती हैं और संगीत उनका इंतज़ार करता है। लय में: गिनती के बाद लय में, हर सुर ताल से मिलाकर जाँचा जाता है। पूरा बजाएँ: शुरू से अंत तक बजाएँ, अंत में एक सारांश के साथ। हर प्रयास ताल-खंड और ताल बताता है और सुधार का तरीक़ा देता है। लगातार कुछ सही प्रयासों के बाद चरण पूरा होता है, और दिन तब पूरा होता है जब उसका मुख्य अभ्यास पूरा बजाया जाए — और अगर उस दिन उसे लय में बजाना है, तो लय में। अभ्यास के लिए कुछ ताल-खंड लूप में चलाएँ, एक हाथ से बजाएँ जबकि मंच दूसरा बजाए, या टेम्पो बदलें; टेम्पो की सीढ़ी पर तीन साफ़ प्रयासों के बाद ताल तेज़ होती है और तीन ग़लतियों के बाद एक सीढ़ी नीचे आती है। आज़माएँ मंच की कुंजियों पर माउस से भी चलता है; लय में और पूरा बजाएँ के लिए MIDI कीबोर्ड चाहिए।","docs.lessons.p3":"ज़ोर से पढ़ें तब तक बंद रहता है जब तक आप इसे चालू न करें। तब आपके कंप्यूटर की अपनी आवाज़ पाठ पढ़ती है, हर शब्द बोले जाते समय जगमगाता है। स्पेस चलाता और रोकता है, ⏹ बंद करता है, और ⏪ या ⏩ दबाए रखने से पीछे या आगे जाते हैं; गति आधी से दुगुनी तक तय करें और इंस्टॉल की गई आवाज़ों में से एक चुनें। घड़ियाँ इस दिन और सभी दिनों में बिताया समय और आपने कितने दिन अभ्यास किया, दिखाती हैं। आपकी प्रगति इसी कंप्यूटर पर रहती है, अलग ऐप में और हर DAW में एक जैसी, और कभी किसी प्रोजेक्ट में नहीं जाती।","docs.mixer.p1":"हर हिस्से की चैनल स्ट्रिप साथ-साथ और मास्टर देखने के लिए M दबाएँ, या मिक्सर टैब। हर स्ट्रिप में एक फ़ेडर, एक पैन नॉब, तीन-बैंड EQ, रूम, इको और हीट, एक कंप्रेसर (जब तक आप चालू न करें, बंद) और ग्रैन्युलर नॉब है, साथ में एक LED मीटर और क्लिप लाइट; मास्टर का अपना फ़ेडर, ग्रैन्युलर नॉब और मीटर है। बारीक हरकत के लिए Shift के साथ फ़ेडर खींचें, या 0 dB के लिए उस पर डबल-क्लिक करें। म्यूट और सोलो कटने की बजाय धीरे से आते-जाते हैं; किसी सोलो पर Ctrl+click करके उसमें एक हिस्सा जोड़ें। हर बदलाव करते समय ही सुनाई देता है और छोड़ते ही पूर्ववत का एक कदम बन जाता है, और प्रोजेक्ट मिक्स को सहेजे रखता है।","docs.mixer.p2":"शीट के नीचे, हर हिस्से का ऑडियो ग्रिप उसे WAV के रूप में आपके DAW में खींचता है, गाने के टेम्पो पर उसकी स्ट्रिप से होकर रेंडर किया हुआ; पूरा मिक्स वैसा ही खिंचता है जैसा आप सुनते हैं और छोड़े गए हिस्सों के नाम बताता है। MIDI ड्रैग हिस्से का फ़ेडर और पैन कंट्रोलर के रूप में साथ ले जाता है और बताता है कि MIDI क्या नहीं ले जा सकता।","docs.envelopes.p1":"किसी हिस्से के टैब पर, एनवेलप बटन उस हिस्से के एनवेलप खोलता है: आवाज़, फ़िल्टर, पिच, पैन और ग्रैन्युलर, हर एक तब तक बंद जब तक आप उसे चालू न करें। कोई बिंदु खींचें, या किसी खंड को मोड़ने के लिए उसका हीरा खींचें; बिंदु जोड़ने के लिए डबल-क्लिक करें, या हटाने के लिए किसी बिंदु पर; किसी बिंदु को चुनकर उसके अंक टाइप करें, या ऐरो कुंजियों से उसे खिसकाएँ। हर एनवेलप में गहराई, समय पैमाना, वेलोसिटी और की ट्रैकिंग, थामा हुआ लूप, टेम्पो से बँधे समय, फिर से ट्रिगर, लेगाटो या हर माप पर रीसेट, और A/B मॉर्फ है। किसी आकार से शुरू करें, एनवेलप को दूसरे हिस्से में कॉपी करें, पूर्ववत करें और फिर से करें, या सब रीसेट करें; गाना बजते समय हर स्वर का एक बिंदु कर्व पर चलता है।","docs.hosted.p1":"हर हिस्सा Handscore के इंस्ट्रूमेंट की जगह आपके अपने किसी VST3 या CLAP इंस्ट्रूमेंट पर बज सकता है। हिस्से के टैब पर या मिक्सर में उसकी स्ट्रिप पर, उसका इंस्ट्रूमेंट बटन चयनकर्ता खोलता है: सबसे पहले Handscore का अपना, फिर हर वह इंस्ट्रूमेंट जो स्कैन को मानक प्लगइन फ़ोल्डरों में और आपके जोड़े फ़ोल्डरों में मिला। एक चुनें और हिस्सा उसके ज़रिए बजता है, उसकी विंडो बस एक क्लिक दूर; प्रोजेक्ट प्लगइन और उसकी आवाज़ सहेज लेता है। हर प्लगइन अपनी अलग प्रोसेस में चलता है, इसलिए जो क्रैश हो वह सिर्फ़ खुद को रोकता है, और उसकी लेटेंसी की भरपाई होती है। हाथ Handscore के इंस्ट्रूमेंट पर रहते हैं, और वह हिस्सा MIDI के रूप में खिंचता है। आपका प्रोजेक्ट जिस प्लगइन का नाम लेता है पर जो इस कंप्यूटर पर नहीं है, उसकी जगह Handscore का अपना ले लेता है, और हिस्सा यह बताता है। इस संस्करण में प्लगइन विंडो Windows पर खुलती हैं।","docs.shortcuts.p1":"सभी शॉर्टकट देखने के लिए ? या ऊपरी पट्टी में शॉर्टकट कुंजी दबाएँ।","docs.project.p1":"अपना DAW प्रोजेक्ट सहेजने पर गाना, उसके बदलाव, उसका मिक्स, उसके बोल, पियानो, दृश्य और क्रेडिट बने रहते हैं, और दोबारा खोलने पर सब कुछ वैसा ही लौट आता है।","docs.theme.p1":"ऊपर दाईं ओर का डार्क थीम स्विच विंडो को लाइट या डार्क करता है। Handscore आपकी पसंद याद रखता है, और आपके कंप्यूटर पर बाकी Freally ऐप्स भी।","docs.language.p1":"Handscore अठारह भाषाएँ बोलता है और आपके सिस्टम की भाषा में शुरू होता है।","docs.privacy.p1":"प्लगइन और स्टैंडअलोन ऐप कभी नेटवर्क का उपयोग नहीं करते। अगर Handscore कभी अचानक रुक जाए, तो एक छोटी रिपोर्ट आपके कंप्यूटर पर रखी जाती है और अगली बार इसके खुलने पर आपको पेश की जाती है; जब तक आप इसे रिपोर्ट करना नहीं चुनते, कुछ नहीं भेजा जाता।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.7.0 पूरा · आगे v0.8.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Handscore आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.ladder.later":"बाद में","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">दस ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Handscore में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.7.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.numbers.lead":"हर आँकड़ा ऐप से ही गिना गया है। कुछ भी अनुमानित नहीं है, और कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया है।","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.later":"उसके बाद, और अभी तय नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Handscore में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","kit.zoom.close":"बंद करें","changelog.9960bf9700bd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.89f5c24a8af1":"मिक्सर। अब हर हिस्सा अपनी चैनल स्ट्रिप से होकर एक मास्टर में बजता है — फ़ेडर, पैन, EQ, रूम, इको, हीट, एक कंप्रेसर और एक ग्रैन्युलर नॉब — मीटर, म्यूट और सोलो के साथ, और यह सब आपके प्रोजेक्ट के साथ सहेजा जाता है। किसी भी हिस्से को, या पूरे मिक्स को, ठीक वैसा ही जैसा आप सुनते हैं, ऑडियो के रूप में अपने DAW में खींचें। एनवेलप एडिटर से हर हिस्से की आवाज़ गढ़ें, और किसी भी हिस्से को अपने किसी VST3 या CLAP इंस्ट्रूमेंट पर बजाएँ।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.8b1d7b62602b":"<strong>मिक्सर।</strong> M दबाएँ: हर हिस्से की स्ट्रिप साथ-साथ और मास्टर — छपे पैमाने वाला फ़ेडर जो आपके पॉइंटर के साथ चलता है, अपनी क्लिप लाइट वाला LED मीटर, नॉब की ग्रिड (लो, मिड, हाई, रूम, इको, हीट), गेन-रिडक्शन लाइट वाला कंप्रेसर, पैन, सोलो और म्यूट। हर हरकत चलते-चलते सुनाई देती है और छोड़ते ही पूर्ववत का एक कदम बन जाती है।","changelog.2869671be357":"<strong>धीरे से आते-जाते म्यूट और सोलो।</strong> कोई हिस्सा कटने की बजाय 30 ms में धीमा होकर बंद होता है और फिर लौटता है, और सोलो सिर्फ़ सोलो किए गए हिस्से सुनाता है — Ctrl+click से एक और जुड़ता है।","changelog.fcb6690799bd":"<strong>ग्रैन्युलर नॉब।</strong> हर स्ट्रिप और मास्टर पर: 0 % पर कुछ नहीं से लेकर 100 % पर कणों, गूँजों और ध्वनि की धुंध के बादल तक — एक ऐसी आवाज़ जो किसी भी हिस्से को एम्बिएंट बना देती है। इसका सीड प्रोजेक्ट से आता है, इसलिए हर रेंडर एक जैसा निकलता है।","changelog.57a83d56df21":"<strong>ऑडियो के रूप में खींचना।</strong> हर हिस्से का ऑडियो ग्रिप उस हिस्से को 24-bit WAV के रूप में खींचता है, गाने के टेम्पो पर उसकी स्ट्रिप से होकर रेंडर किया हुआ; पूरा मिक्स वैसा ही खिंचता है जैसा आप सुनते हैं और छोड़े गए हिस्सों के नाम बताता है।","changelog.b2176c506737":"<strong>मिक्स साथ ले जाने वाले MIDI ड्रैग।</strong> किसी हिस्से का फ़ेडर और पैन फ़ाइल में CC 7 और CC 10 के रूप में जाते हैं, और ग्रिप बताता है कि MIDI क्या नहीं ले जा सकता।","changelog.5b174d5cb7c6":"<strong>एनवेलप एडिटर।</strong> हर जनरेटर के आवाज़, फ़िल्टर, पिच, पैन और ग्रैन्युलर एनवेलप, हर एक तब तक बंद जब तक आप उसे चालू न करें: खींचने के लिए बिंदु, मोड़ने के लिए खंड, थामा हुआ लूप, टेम्पो से बँधे समय, वेलोसिटी और की ट्रैकिंग, फिर से ट्रिगर या लेगाटो, A/B मॉर्फ, शुरुआती आकार, दूसरे हिस्से में कॉपी, पूर्ववत और फिर से करना, और कर्व पर चलता हर स्वर का एक लाइव बिंदु।","changelog.747aa74c96df":"<strong>आपके अपने इंस्ट्रूमेंट।</strong> हर हिस्सा Handscore के इंस्ट्रूमेंट की जगह आपके अपने किसी VST3 या CLAP इंस्ट्रूमेंट पर बज सकता है: हिस्से के टैब या स्ट्रिप पर, स्कैन में मिले इंस्ट्रूमेंट में से उसे चुनें, वहीं से उसकी विंडो खोलें, और आपका प्रोजेक्ट प्लगइन और उसकी आवाज़ सहेज लेता है। हर प्लगइन अपनी अलग प्रोसेस में चलता है, इसलिए जो क्रैश हो वह सिर्फ़ खुद को रोकता है, और उसकी लेटेंसी की भरपाई होती है। हाथ Handscore के इंस्ट्रूमेंट पर रहते हैं, और वह हिस्सा MIDI के रूप में खिंचता है।","changelog.ddebf2581fd7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.1d54e0107a4f":"पाठ। अब Handscore पियानो सिखाता है, दिन-ब-दिन, आपके बिल्कुल पहले सुरों से लेकर लगभग ग्रेड 2 के स्तर तक: दो खंडों में 400 दिन, शुरुआती और प्राथमिक, हर दिन अपना एक निर्देशित सत्र। हाथ हर अभ्यास किसी भी दृश्य से करके दिखाते हैं, फिर पाठ्यक्रम आपको अपने MIDI कीबोर्ड पर बजाते हुए सुनता है और तभी आगे बढ़ता है जब सब सही हो। ज़ोर से पढ़ें चालू करें और आपके कंप्यूटर की अपनी आवाज़ आपको पाठ पढ़कर सुनाती है, हर शब्द बोले जाते समय जगमगाता है।","changelog.7cf885e0b28b":"<strong>स्टूडियो में ही पाठ।</strong> मोड चुनें → पाठ पियानो पाठ्यक्रम खोलता है: बाईं ओर पाठ्यक्रम का नक्शा और दिन के चरण, बीच में मंच, उसके नीचे पाठ का पाठ्य। पाठ से बाहर निकलें आपको उसी गीत पर लौटा देता है जिसे आप छोड़कर आए थे।","changelog.1c23de3f48f7":"<strong>पियानो के 400 दिन।</strong> शुरुआती (दिन 1–90) और प्राथमिक (दिन 91–400): बैठने का ढंग और हाथ का आकार, पाँच-उँगली की स्थितियाँ, ग्रैंड स्टाफ़ पढ़ना, लय, कॉर्ड, पेडल, स्केल और आरपेजियो, दोनों हाथ साथ और बजाने के लिए रचनाएँ, हर सप्ताह दोहराने का एक दिन और पहले का काम जो समय आने पर लौटता है।","changelog.1a00ed521da6":"<strong>सुनना और जाँचना, तीन तरीक़ों से।</strong> <em>आज़माएँ</em>: बजाने वाली कुंजियाँ जगमगाती हैं और संगीत उनका इंतज़ार करता है। <em>लय में</em>: गिनती के बाद लय में, हर सुर ताल से मिलाकर जाँचा जाता है। <em>पूरा बजाएँ</em>: शुरू से अंत तक बजाएँ, अंत में एक सारांश के साथ।","changelog.93f77c21d390":"<strong>शिक्षक जैसी प्रतिक्रिया।</strong> हर प्रयास ताल-खंड और ताल बताता है और सुधार का तरीक़ा देता है — छूटा हुआ सुर, जल्दी या देर से, जुड़ा या अलग, पेडल — और बताता है कि क्या अच्छा रहा।","changelog.03b65d4d96a6":"<strong>अभ्यास के औज़ार।</strong> कुछ ताल-खंडों को लूप में चलाएँ, एक हाथ से बजाएँ जबकि मंच दूसरा हाथ बजाए, टेम्पो की सीढ़ी चढ़ें (तीन साफ़ प्रयासों के बाद एक सीढ़ी ऊपर, तीन ग़लतियों के बाद एक नीचे) और किसी भी दृश्य में उँगलियों के अंकों के साथ धीमे प्रदर्शन देखें। जैसे-जैसे आप कुंजियों के नाम सीखते हैं, वे धुँधले होते जाते हैं।","changelog.deb6f2d0e7f9":"<strong>ज़ोर से पढ़ें।</strong> जब तक आप इसे चालू न करें, बंद रहता है, और याद रखा जाता है। आपके कंप्यूटर की आवाज़ पाठ पढ़ती है, बोला जा रहा शब्द कराओके स्क्रीन की तरह जगमगाता है और पाठ्य उसे दिखाए रखने के लिए सरकता है। स्पेस से चलाएँ और रोकें, बंद करें, पीछे या आगे जाने के लिए ⏪ या ⏩ दबाए रखें, गति आधी से दुगुनी तक तय करें और आवाज़ चुनें; एक घड़ी बीता और बचा हुआ पढ़ने का समय दिखाती है।","changelog.b9d693ff0bb1":"<strong>आपकी प्रगति, सहेजी हुई।</strong> जो दिन आप पार कर चुके, हर पाठ में और सब में मिलाकर बिताया समय, और जिन दिनों आपने अभ्यास किया, दिनों, घंटों, मिनटों और सेकंडों में — इसी कंप्यूटर पर, अलग ऐप में और हर DAW में। जारी रखें ठीक वहीं खोलता है जहाँ आप रुके थे: दिन, चरण और शब्द।","changelog.2f7168838eb6":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.cb681d22c8c6":"ऊपर से और बगल से दृश्य। हाथों को सामने से, ठीक ऊपर से या बगल से देखें, और संगीत बजते हुए एक दृश्य से दूसरे पर सरकें — कुंजियाँ, हाथ और जलते हुए सुर एक भी ताल नहीं चूकते। ऊपर से देखने पर ग्रैंड पियानो अपना ढक्कन बंद कर लेता है और स्वरलिपियाँ उस पर सपाट पड़ी रहती हैं, पढ़ने के लिए तैयार; बगल से हाथों का आकार दिखता है: हर उँगली कैसे मुड़ती है और हर कुंजी कितनी नीचे जाती है।","changelog.92ffe6279372":"<strong>तीन दृश्य: सामने, ऊपर और बगल।</strong> मंच के ऊपरी दाएँ कोने में दृश्य का नॉब घुमाएँ, या अगले दृश्य के लिए V और पिछले के लिए Shift+V दबाएँ। आपका प्रोजेक्ट दृश्य याद रखता है।","changelog.51b3e3c98cbc":"<strong>बिना रुकावट का बदलाव।</strong> कैमरा पियानो के आर-पार कभी गए बिना एक दृश्य से अगले पर सरकता है, और हलचल के दौरान संगीत बजता रहता है: हर कुंजी, हर हाथ और हर जलता सुर ठीक वहीं होता है जहाँ कैमरा स्थिर रहने पर होता।","changelog.24e5e2980ffb":"<strong>ऊपर: कुंजियाँ और हाथ ऊपर से।</strong> ग्रैंड पियानो अपनी टेक मोड़ता है, म्यूज़िक डेस्क को सपाट लिटाता है और ढक्कन बंद करता है; स्वरलिपियाँ डेस्क से उठती हैं, कुंजियों के ऊपर रुकती हैं और बंद ढक्कन पर अगल-बगल लेट जाती हैं, आपकी जगह से सीधी पढ़ी जा सकें इस तरह। अपराइट पियानो पर स्वरलिपियाँ ऊपरी ढक्कन पर लेटती हैं।","changelog.ea29eaefbaec":"<strong>बगल: हाथों की प्रोफ़ाइल।</strong> कैमरा कुंजियों की ऊँचाई पर ऊँचे सुरों वाले सिरे से कीबोर्ड के साथ-साथ देखता है — या दृश्य के नॉब के नीचे <em>बाईं ओर से</em> चुनकर, गहरे सुरों वाले सिरे से — और स्वरलिपियाँ डेस्क पर उसकी ओर घूम जाती हैं ताकि पढ़ी जा सकें।","changelog.49ab9c89770a":"<strong>हर ओर से हाथ।</strong> वे जिन कुंजियों को बजाते हैं उन पर अपनी छाया डालते हैं, और ऊपर से कोई उँगली का सिरा कभी किसी कुंजी या पियानो के ढाँचे में नहीं धँसता।","changelog.31bd22333d53":"<strong>हर दृश्य में स्वरलिपि पास से।</strong> उस पर क्लिक करें, या 1 से 5 दबाएँ; Esc दृश्य पर लौटाता है।","changelog.7acb71645827":"<strong>हर दृश्य में सुचारु।</strong> दृश्य या पियानो के हर बदलाव के बाद Handscore फिर से जाँचता है कि मंच कितना सुचारु चल रहा है, और अगर वह धीमा हो गया हो तो गुणवत्ता घटाता है और आपको बताता है।","changelog.d524626e7e53":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.1afdc18898f2":"बनाएँ, पढ़ें और खींचें। 73 शैलियों, 1,507 कलाकारों या 833 प्रोड्यूसरों में से खोजें, बनाएँ दबाएँ, और चार हिस्से — कॉर्ड, धुन, प्रति-धुन और बेसलाइन — उसी शैली में लिखे जाते हैं और हाथ उन्हें पियानो पर बजाते हैं। हर हिस्सा पियानो के म्यूज़िक-डेस्क पर असली शीट म्यूज़िक की तरह छपता है, पूरे स्कोर के साथ, और हर स्वर बजते ही जगमगाता है। किसी हिस्से को, या पूरे गाने को, सीधे अपने DAW में खींचें, किसी भी स्वर को उसके अपने पियानो रोल में बदलें, और MIDI या शीटों का PDF अपने क्रेडिट्स के साथ निर्यात करें।","changelog.e5fa15165f43":"<strong>किसी भी शैली में बनाएँ।</strong> बाईं ओर के पैनल में कोई शैली, कलाकार या प्रोड्यूसर खोजें (ऐप के किनारे पर उसका टैब उसे दिखाता और छिपाता है) और बनाएँ या G दबाएँ। पास के चिप्स स्केल का मूल स्वर, स्केल (41 विकल्प), मूड, टेम्पो (20 से 999 BPM; संख्या को ऊपर या नीचे खींचें), जटिलता और 4 या 8 बार तय करते हैं, और हर चिप बताता है कि गाना किसमें बना। <em>DAW का अनुसरण</em> आपके प्रोजेक्ट के टेम्पो पर लिखता है।","changelog.9b105b8264c8":"<strong>चार हिस्से, हाथों से बजते हुए।</strong> कॉर्ड, धुन, प्रति-धुन और बेसलाइन — दो हाथों के लिए सजाए हुए (<em>बजाने योग्य</em>) या ठीक जैसे लिखे गए (<em>मूल</em>)। हर रचना अपने 4 या 8 बार भरती है, और 4 से 8 पर जाने पर पहले चार दोहराए जाते हैं।","changelog.99862da9695f":"<strong>असली शीट म्यूज़िक।</strong> हर हिस्सा म्यूज़िक-डेस्क पर एक पन्ने की तरह छपता है, अपने शीर्षक और पृष्ठ संख्या के साथ, और बगल में सभी हिस्सों का पूरा स्कोर। चलते प्लेहेड के नीचे हर स्वर-शीर्ष बजते ही जगमगाता है, और लंबा हिस्सा बजते-बजते अपने पन्ने पलटता है। किसी शीट पर क्लिक करें, या 1 से 5 दबाएँ, उसे पास लाने के लिए; Esc वापस ले जाता है।","changelog.4ed6b96e134b":"<strong>शीट ट्रे।</strong> मंच के नीचे, हर हिस्सा सोलो, म्यूट, लॉक और एक नए टेक के साथ। लॉक किया हुआ हिस्सा दोबारा बनाने पर बना रहता है।","changelog.2b9c198c01ea":"<strong>अपने DAW में खींचें।</strong> एक हिस्से को, या <em>सब खींचें</em> से पूरे गाने को, उसकी शीट से अपने DAW में MIDI के रूप में खींचें।","changelog.471d0e4ba86d":"<strong>निर्यात।</strong> किसी हिस्से या पूरे गाने का MIDI सहेजें — हर स्वर की वेलोसिटी, हर हिस्से का स्तर और पैन, टेम्पो और ताल-चिह्न के साथ।","changelog.142257343a9f":"<strong>PDF में निर्यात।</strong> शीटों का PDF, एक कवर पेज के साथ: शीर्षक, टेम्पो, मूल स्वर और स्केल, अवधि, बार, कुल स्वर, हर हिस्से और हर पन्ने के हिसाब से, और वाद्य। क्रेडिट जोड़ें — लेखक, गायक, प्रोड्यूसर, इस्तेमाल किए गए सैंपल और उनका स्रोत, रिकॉर्ड लेबल — टाइप करते समय सुझाए गए नामों के साथ।","changelog.1531fe3dfe30":"<strong>हर हिस्से के लिए एक टैब।</strong> ऊपर मंच, धुन, कॉर्ड, प्रति-धुन और बेसलाइन; हर हिस्से का टैब अपने पियानो रोल, एक म्यूट बिंदु, सोलो और उसे खाली करने वाले × के साथ।","changelog.dc61e3f5b735":"<strong>स्वरों को संपादित करें।</strong> किसी भी हिस्से के रोल में स्वरों को चुनें, खिसकाएँ, लंबा करें, मिटाएँ, कॉपी करें, चिपकाएँ और दोहराएँ; दायाँ क्लिक करके खींचने से स्वर हटते और लौटते हैं। एक या दो बार की गिनती के बाद MIDI कीबोर्ड से रोल में रिकॉर्ड करें। हर हिस्से का अपना गेन और पैन है।","changelog.0cb3c4c9fd20":"<strong>रोल पर स्केल।</strong> रोल को गाने के स्केल पर या स्वरों वाली पंक्तियों पर समेटें; स्केल की पंक्तियाँ रंगी होती हैं और उससे बाहर का स्वर चिह्नित होता है।","changelog.0ef6f26c2429":"<strong>एक कुंजी से कॉर्ड।</strong> इन्हें चालू करें और एक कुंजी गाने के मूल स्वर में 3, 4 या 5 स्वरों का कॉर्ड बजाती है — माउस, कंप्यूटर कीबोर्ड या MIDI कीबोर्ड से।","changelog.d9cada2e85a6":"<strong>घोस्ट स्वर।</strong> जैसे-जैसे आप बनाते हैं, अगला स्वर या कॉर्ड हल्का-सा सुझाया जाता है; Tab उसे रखता है, एक क्लिक एक को रखता है, और कहीं और बनाने से सुझाव हट जाते हैं।","changelog.01aa58d9ab50":"<strong>बोल।</strong> धुन या प्रति-धुन के नीचे शब्द लिखें, अक्षर चिह्नित करके: वे शीट पर छपते हैं और गाए जाते समय जगमगाते हैं। हर पंक्ति के पास एक गिनती बताती है कि वह अपने बार में समाती है या नहीं। टाइप करते समय शब्द का बाकी हिस्सा सुझाया जाता है (Tab उसे ले लेता है) और ग़लत वर्तनी सुधारी जाती है, जब तक आप अपना शब्द रखने के लिए चेकमार्क न छुएँ या Shift+Tab न दबाएँ।","changelog.407e049442f6":"<strong>टेक, सपना 1–3 और फिर सपना।</strong> किसी भी हिस्से के तीन नए संस्करण, आपके मौजूदा के बगल में; एक चुनें और रख लें। किसी क्लासिक का फिर सपना उसे आपका अपना नया गाना बना देता है।","changelog.a2ae6ec40472":"<strong>सीड।</strong> हर रचना अपना सीड और हर हिस्से का टेक सीड दिखाती है, कॉपी के साथ। किसी गाने का सीड चिपकाएँ उसे फिर से बनाने के लिए, या किसी हिस्से का टेक सीड वह टेक वापस लाने के लिए।","changelog.7403cd98e6cb":"<strong>इतिहास।</strong> आपकी हर रचना में पीछे और आगे — हर एक ठीक वैसी ही लौटती है और रीस्टार्ट के बाद भी बनी रहती है। नई रचना कभी पुरानी को नहीं दोहराती।","changelog.3c500d42ebde":"<strong>क्लासिक सीखने के लिए हैं, ले जाने के लिए नहीं।</strong> किसी क्लासिक से सिर्फ़ उसके कॉर्ड बाहर जा सकते हैं। बनाया गया कोई गाना जिसकी धुन, प्रति-धुन या बेसलाइन किसी जानी-मानी धुन से मिलती हो, उस हिस्से को ऐप में ही रखता है और कारण बताता है।","changelog.ce67fa868077":"<strong>कीबोर्ड शॉर्टकट का डायलॉग।</strong> सभी शॉर्टकट देखने के लिए ? या ऊपरी पट्टी में उसकी कुंजी दबाएँ।","changelog.4ca2136708d7":"<strong>आपका प्रोजेक्ट याद रखता है।</strong> अपना DAW प्रोजेक्ट सहेजने पर गाना, उसके बदलाव, उसका मिक्स, उसके बोल, पियानो, दृश्य और क्रेडिट बने रहते हैं, और दोबारा खोलने पर सब कुछ वैसा ही लौट आता है।","changelog.2a6141e43be0":"बदला गया","changelog.e60841228886":"<strong>टाइमलाइन का प्रीव्यू बड़ा है</strong>, और उस पल गाए जा रहे शब्द दिखाता है।","changelog.1dca7b1d60db":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.d35d794c003e":"यथार्थवादी हाथ। अब Handscore के मंच पर हाथों की एक जोड़ी पियानो वैसे ही बजाती है जैसे कोई पियानोवादक बजाता — हर उंगली उस अंश के लिए चुनी हुई, स्केल पर अंगूठा नीचे से निकलता हुआ, और जब संगीत में हाथों को एक-दूसरे के पार जाना हो तो एक हाथ उठकर दूसरे के ऊपर से जाता हुआ। सीखने के लिए बासठ पब्लिक-डोमेन क्लासिक्स तैयार हैं, Mary Had a Little Lamb से लेकर Silent Night और The Star-Spangled Banner तक, और मंच के नीचे का ट्रांसपोर्ट आपको रोकने, पीछे करने, आगे करने या किसी भी पल तक खींचने देता है, और साथ-साथ आप नोट सुनते जाते हैं।","changelog.0390e4a43a0a":"<strong>कीबोर्ड पर यथार्थवादी हाथ।</strong> कलाई पर ख़त्म होने वाले दो हाथ चारों पियानो पर हर नोट बजाते हैं: हर उंगली वैसे ही चुनी हुई जैसे कोई पियानोवादक चुनता, स्केल पर अंगूठा नीचे से निकलता हुआ, चौड़े कॉर्ड्स तक पहुँच, अंगूठा करवट लेटा और हल्का मुड़ा हुआ, और पार करने के लिए एक हाथ उठकर दूसरे के ऊपर से जाता हुआ। जब कुछ नहीं बज रहा होता, तो वे कुंजियों पर तैयार टिके रहते हैं।","changelog.2c009dbabcfe":"<strong>नोट बजने से पहले ही तय फ़िंगरिंग।</strong> Handscore संगीत बजने से पहले तय करता है कि हर नोट कौन-सा हाथ बजाएगा और किस उंगली से, ताकि हाथ बाद में नहीं, बल्कि कुंजियों के नीचे जाते ही पहुँचें।","changelog.216f61cb53a3":"<strong>मोड चुनें।</strong> ऊपर बाईं ओर के बटन (या P) पर अब <em>मोड चुनें</em> लिखा है और यह आपके विकल्प श्रेणी के अनुसार खोलता है: वाद्य, क्लासिक गीत, अंश, और पाठ (बाद के संस्करण में आएँगे)।","changelog.44952a5f65fd":"<strong>सीखने के लिए बासठ क्लासिक्स।</strong> बच्चों के गीत, क्रिसमस गीत और कैरल, लोकगीत, स्पिरिचुअल और गान, क्लासिकल थीम और पियानो के लोकप्रिय गीत — Chopsticks, Jingle Bells, Silent Night, Ode to Joy, Für Elise, The Entertainer, The Star-Spangled Banner और भी बहुत कुछ — हर एक दो हाथों के लिए अरेंज किया गया, धुन दाएँ हाथ में और कॉर्ड्स बाएँ में। इन्हें शीर्षक या संगीतकार से खोजें। हर एक पब्लिक डोमेन में है।","changelog.d8fc29c977d3":"<strong>देखने के लिए अंश।</strong> एक स्केल, एक ii–V–I, एक आर्पेजियो और एक क्रॉसिंग, हर एक काम करते हाथों की एक झलक।","changelog.d0ff9a5e5f3f":"<strong>ट्रांसपोर्ट।</strong> मंच के नीचे चलाएँ, रोकें, बंद करें, पीछे करें और आगे करें, साथ में एक टाइमलाइन जो गीत का समय और उसके बार दिखाती है। उस पल के हाथ एक छोटे पूर्वावलोकन में देखने के लिए टाइमलाइन पर पॉइंटर ले जाएँ। उस पर खींचें, या पीछे करें या आगे करें को दबाए रखें, और आप हर वह नोट सुनते हैं जिससे आप गुज़रते हैं, किसी भी दिशा में।","changelog.197a823169eb":"<strong>एक मेट्रोनोम।</strong> इसे चालू करें, तो हर बीट पर एक क्लिक होता है, हर बार की पहली बीट ऊँची, जबकि इसके <em>M</em> के पास के बिंदु बीट दिखाते हैं।","changelog.f94e5b4b235f":"<strong>स्पेस चलाता और रोकता है।</strong>","changelog.dd397e7c80b2":"<strong>वाद्य बटन अब मोड चुनें है</strong>, और आप जो पियानो चुनते हैं वह वाद्यों में <em>वर्तमान</em> के रूप में चिह्नित होता है।","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"असली पियानो। Handscore के मंच पर अब चार पियानो हैं — एक कॉन्सर्ट ग्रैंड, एक पार्लर ग्रैंड, एक स्टूडियो अपराइट और एक पुराना सलून अपराइट — हर एक स्टूडियो जैसी रोशनी में और हर एक की अपनी आवाज़। किसी कुंजी पर क्लिक करें या अपने DAW से बजाएँ, और पियानो बज उठता है: कुंजी नीचे जाती है, उसका नाम धुंधला पड़ जाता है, और सस्टेन पेडल वह थामे रखता है जो आप छोड़ देते हैं। पियानो पिकर से आप कोई पियानो चुनने से पहले उसे सुन सकते हैं।","changelog.a8f76e859570":"<strong>चार असली पियानो।</strong> Grand Piano, Acoustic Piano, Upright Piano और Honky-Tonk Piano, हर एक का अपना आकार, फ़िनिश और आवाज़, दोनों थीम में।","changelog.6f544a8bd67f":"<strong>कुंजियाँ बजाएँ।</strong> किसी कुंजी को सुनने के लिए उस पर क्लिक करें, या कुंजियों पर से सरकाते हुए उन्हें एक-एक करके बजाएँ। आपके DAW से आने वाला MIDI पियानो बजाता है और उसकी कुंजियाँ हिलाता है, और सस्टेन पेडल आपके छोड़े हुए सुरों को तब तक थामे रखता है जब तक आप उससे पैर नहीं उठा लेते।","changelog.3f265130a08f":"<strong>पियानो जैसी चलने वाली कुंजियाँ।</strong> हर कुंजी अपने संतुलन बिंदु पर घूमते हुए नीचे जाती है, जितनी ज़ोर से बजाई जाए उतनी तेज़ी से, और नीचे रहने तक उसका नाम धुंधला रहता है और ऊपर उठने पर लौट आता है।","changelog.7fd2c1ed940d":"<strong>पियानो पिकर।</strong> ऊपर बाईं ओर का वाद्य बटन (या P) चार कार्ड खोलता है। <em>पूर्वावलोकन</em> पियानो बदले बिना उस पियानो पर एक छोटी धुन बजाता है; <em>चुनें</em> उसे मंच पर रख देता है, पिछले पियानो से क्रॉसफ़ेड करते हुए। आपकी पसंद आपके प्रोजेक्ट के साथ सहेजी जाती है।","changelog.72aa386a33ff":"<strong>आपके कंप्यूटर के अनुरूप गुणवत्ता।</strong> Handscore मापता है कि आपका कंप्यूटर मंच को कितनी तेज़ी से बनाता है, और उस गुणवत्ता पर टिक जाता है जिसे वह सहजता से बनाए रख सके।","changelog.1246fc93bca0":"ठीक किया गया","changelog.58e041aeca75":"<strong>व्यस्त कंप्यूटर पर भी कुंजियाँ पीछे नहीं रहतीं।</strong> जब कंप्यूटर धीरे बना रहा होता था, तब बजाई गई कुंजी ऊपर ही रह सकती थी, या उसका नाम आधा धुंधला रह सकता था; अब वह हमेशा वहीं रुकती है जहाँ आपके बजाने ने उसे छोड़ा।","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"नींव। Freally Handscore CLAP और VST3 प्लगइन के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, अपने लाइसेंस की स्वीकृति माँगता है, और अपने मंच पर खुलता है: असली पियानो के माप में 88 कुंजियों वाला कीबोर्ड, जिसकी हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है। अभी कुछ भी जनरेट नहीं होता — वह असली पियानो और हाथों के साथ आएगा।","changelog.37cee751dc57":"<strong>प्लगइन और स्टैंडअलोन ऐप।</strong> Windows पर CLAP और VST3 (AU एक Mac पर बनाया जाता है), और एक स्टैंडअलोन ऐप जो अपने टाइटल बार और टास्कबार में Handscore का आइकन दिखाता है।","changelog.bf0d03d43bfd":"<strong>लाइसेंस अनुबंध सबसे पहले।</strong> जब तक आप सहमत नहीं होते, Handscore कुछ नहीं करता। आपका जवाब आपके कंप्यूटर पर रखा जाता है और हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी।","changelog.28bc52fb055e":"<strong>मंच।</strong> 88 कुंजियों वाला कीबोर्ड, A0 से C8 तक, असली पियानो के माप में, जो विंडो की पूरी चौड़ाई भरता है। हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है — सफ़ेद कुंजियों पर गहरी स्याही में, काली कुंजियों पर सफ़ेद में — और कुंजी दबी रहने तक छिपा रहता है।","changelog.d51fdbedfc0e":"<strong>लाइट और डार्क।</strong> ऊपर दाईं ओर का स्विच; Handscore आपकी पसंद याद रखता है।","changelog.9e0609310c1a":"<strong>अठारह भाषाएँ।</strong> Handscore आपके सिस्टम की भाषा में शुरू होता है।","changelog.f1cf7c9dfaa8":"<strong>एक 3D व्यू जो बताता है कि वह कब नहीं बना सकता।</strong> WebGL 2 के बिना कोई विंडो कुछ भी न दिखाने के बजाय समझाती है कि इसे कैसे चालू करें।","changelog.0fe089d138d3":"<strong>क्रैश रखे जाते हैं, कभी भेजे नहीं जाते।</strong> अगर Handscore कभी अचानक रुक जाए, तो अगली बार शुरू होने के लिए एक छोटी रिपोर्ट आपके कंप्यूटर पर रखी जाती है। जब तक आप इसे रिपोर्ट करना नहीं चुनते, आपके कंप्यूटर से कुछ भी बाहर नहीं जाता।"};
